head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.search_ACCNT_PTTN = ""; // 검색시 수정된 유형
scwin.search_IND_PTTN = "";
// 세션정보를 얻기위한 함수사용
scwin.fn_SetPar;
scwin.fn_GetPar;
scwin.queryId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.firstSet();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00500.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        if (grd_ComList.getRowCount() <= 0) {
            await $c.win.alert("조회된 데이터가 없습니다.");
            return;
        }
        $c.data.downloadGridViewExcel(grd_ComList, {fileName: "요약재무정보", type: "2"}); // 엑셀 다운로드
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00500.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        scwin.initialize();
        await scwin.inspecOp();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00500.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_CoSearch_onclick
 * @description img_CoSearch 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_CoSearch_onclick = async function() {
    try {
        await scwin.comSrchOpen();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00500.img_CoSearch_onclick" });
    }
};

/**
 * @method
 * @name txb_CoSnm_onchange
 * @description txb_CoSnm 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_CoSnm_onchange = function() {
    try {
        // 조회조건이 변경된 경우 초기화.
        txb_KisCd.setValue("");
        txb_IndPttn.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00500.txb_CoSnm_onchange" });
    }
};

/**
 * @method
 * @name txb_CoSnm_onkeydown
 * @description txb_CoSnm 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_CoSnm_onkeydown = async function() {
    try {
        // 기업명 키다운.
        if (event.keyCode === 13) {
            $c.frame.focus();
            if (txb_CoSnm.getValue() === "") {
                // 기업검색팝업 오픈
                await scwin.comSrchOpen();
            } else {
                // 기업정보 조회
                await scwin.comInfoSrch();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00500.txb_CoSnm_onkeydown" });
    }
};

/**
 * @method
 * @name grd_ComList_OnDblClick
 * @description grd_ComList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_ComList_OnDblClick = function(row, colid) {
    try {
        scwin.openDetail(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00500.grd_ComList_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_inspecOp_OnLoadCompleted
 * @description dts_inspecOp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_inspecOp_OnLoadCompleted = async function(rowcount) {
    try {
        if (cmb_searchType.getValue() === '1') {
            searchTypeNM = '구성비';
        } else {
            searchTypeNM = '증감률';
        }
        for (let i = 1; i <= dts_inspecOp.getRowCount(); i++) {
            const fiscal_typ = dts_inspecOp.getCellData(i, "FISCAL_TYP");
            let fiscal_mm_text = "";
            if (fiscal_typ === 'K') fiscal_mm_text = '온기';

            else if (fiscal_typ === 'T') fiscal_mm_text = '3분기(누적)';

            else if (fiscal_typ === 'B') fiscal_mm_text = '반기';

            else if (fiscal_typ === 'F') fiscal_mm_text = '1분기';

            else if (fiscal_typ === 'X') fiscal_mm_text = '2분기';

            else if (fiscal_typ === 'Y') fiscal_mm_text = '3분기';

            else if (fiscal_typ === 'Z') fiscal_mm_text = '4분기';
            $c.cm.setColumnProp(grd_ComList, i + "date", "Name", dts_inspecOp.getCellData(i, "FISCAL_YYYY") + "년 " + dts_inspecOp.getCellData(i, "FISCAL_MM") + "월 (" + fiscal_mm_text + ")");
            const ISU_ADMIN_YN = (dts_inspecOp.getCellData(i, "ISU_ADMIN_YN") === "Y") ? "관리종목" : "관련없음";
            const AUDT_OPIN_LDIV = dts_inspecOp.getCellData(i, "AUDT_OPIN_LDIV");
            const AUDT_OPIN_MDIV = dts_inspecOp.getCellData(i, "AUDT_OPIN_MDIV");
            $c.cm.setColumnProp(grd_ComList, "inspection" + String(i, scwin.getOpiText(AUDT_OPIN_LDIV + AUDT_OPIN_MDIV) + " / " + ISU_ADMIN_YN), "Name", '');
            $c.cm.setColumnProp(grd_ComList, "data_op" + i + "_1", "Name", "금액");
            $c.cm.setColumnProp(grd_ComList, "data_op" + i + "_2", "Name", searchTypeNM);
        }
        await scwin.search3();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00500.dts_inspecOp_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ComList_OnLoadCompleted
 * @description dts_ComList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ComList_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_ComList.errorMsg) {
            await $c.win.alert(dts_ComList.errorMsg);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00500.dts_ComList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name panel_page_onclick
 * @description 「0」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.panel_page_onclick = async function() {
    try {
        await scwin.accntCdOpen();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00500.panel_page_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
// 검색시 수정된 업종유형

/**
 * @method
 * @name inspecOp
 * @description 재무 환경데이터를 조회한다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inspecOp = async function() {
    if (txb_CoSnm.getValue() === "") {
        await $c.win.alert("조회 기업을 검색해 주세요");
        txb_CoSnm.focus();
        return false;
    }

    // 분기별
    const queryId = "krx.lds.stf.fis.select.InspecOpValue2";

    // 동기별
    if (cmb_shType.getValue() === "1") scwin.queryId = "krx.lds.stf.fis.select.InspecOpValue";

    const sbmOptions = {
        id : "sbm_dts_inspecOp",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_inspecOp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search3
 * @description 재무 데이터를 조회한다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search3 = async function() {

    // 자본변동표인경우 계정코드가 요약이 없어 재무전체로 변경한다
    if (cmb_type.getValue() === "6") {
        rdo_TYPE.setValue(2);
    }

    // 제조업일경우 유형을 4(현금흐름표)일경우 6으로 바꿔준다 6(자본변동표)인경우 -> 업종유형을 2로 바꿔준다
    scwin.search_ACCNT_PTTN = cmb_type.getValue();
    scwin.search_IND_PTTN = txb_IndPttn.getValue();
    if (txb_IndPttn.getValue() === "1") {
        if (cmb_type.getValue() === "4") {
            scwin.search_ACCNT_PTTN = "6";
        } else if (cmb_type.getValue() === "6") {
            scwin.search_IND_PTTN = "2";
        }
    }
    if (cmb_shType.getValue() === "1") {
        scwin.queryId = "krx.lds.stf.fis.select.sameTime";
    } else {
        scwin.queryId = "krx.lds.stf.fis.select.finQuarter";
    }

    // alert("queryId="+queryId);

    const sbmOptions = {
        id : "sbm_dts_ComList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ComList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name comInfoSrch
 * @description com Info Srch 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.comInfoSrch = async function() {
    // 데이터셋 초기화
    dts_ComList.removeAll();
    const sbmOptions = {
        id : "sbm_dts_ComInfo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ComInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 조회결과가 1개이면 기업개황 조회 아니면 기업팝업 오픈.
    if (dts_ComInfo.getRowCount() === 1) {
        // 조회조건에 값을 세팅하고..
        txb_KisCd.setValue(dts_ComInfo.getCellData(0, "KIS_CD"));
        txb_IndPttn.setValue(dts_ComInfo.getCellData(0, "IND_PTTN"));
        await scwin.inspecOp(); // 기업개황 조회

    } else {
        await scwin.comSrchOpen(); // 기업검색 팝업 오픈

    }
};

/**
 * @method
 * @name firstSet
 * @description 결산연도를 가져온다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.firstSet = async function() {
    const sbmOptions = {
        id : "sbm_dts_AcntclsDt",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_AcntclsDt=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.initialize();
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParKisCd
 * @description 팝업으로 값을 넘김.
 * @returns {void}
 * @hidden N
 */
scwin.getParKisCd = function() {
    let arrPar = new Array();
    arrPar[0] = txb_CoSnm.getValue(); // 기업명
    return arrPar;
};

/**
 * @method
 * @name setParKisCd
 * @description 팝업에서 넘어온 값 세팅.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParKisCd = async function(arrPar) {
    txb_CoSnm.setValue(arrPar[0].CO_SNM); // 기업명
    txb_KisCd.setValue(arrPar[0].KIS_CD); // 기업코드

    if (txb_KisCd.getValue() !== "") {
        await scwin.inspecOp();
    }
};

/**
 * @method
 * @name comSrchOpen
 * @description 기업검색 팝업
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.comSrchOpen = async function() {
    const options = {
        id: "ULDFIS00100_P1",
        title: "기업 검색",
        type: "browserPopup",
        width: 640 + 20,
        height: 445 + 45,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("./ULDFIS00100_P1.gfm", options);
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function() {
    // 필수항목 체크.
    if (txb_CoSnm.getValue() === "") {
        await $c.win.alert("기업명을 입력하세요.");
        txb_CoSnm.focus();
        return false;
    }

    // 기업명은 있는데 기업코드가 없는 경우
    if (txb_CoSnm.getValue() !== "" && txb_KisCd.getValue() === "") {
        await scwin.comInfoSrch();
        return false;
    }
    return true;
};

/**
 * @method
 * @name setParKisCd
 * @description 팝업에서 넘어온 값 세팅.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParKisCd = async function(arrPar) {
    txb_CoSnm.setValue(arrPar[0].CO_SNM); // 기업명
    txb_KisCd.setValue(arrPar[0].KIS_CD); // 기업코드
    txb_IndPttn.setValue(arrPar[0].IND_PTTN);
    if (txb_KisCd.getValue() !== "") {
        await scwin.inspecOp();
    }
};

/**
 * @method
 * @name openDetail
 * @description 선택된 값을 오프너에 전달한다.
 * @param {*} v_Currow v_Currow
 * @returns {void}
 * @hidden N
 */
scwin.openDetail = function(v_Currow) {
    if (v_Currow === undefined) {
        v_Currow = dts_ComList.getRowPosition();
    }
    let arrPar = new Array();
    if (scwin.fn_SetPar !== undefined) {
        arrPar[0] = {
            nm: dts_ComList.getCellData(v_Currow, "nm"), // 기업명
            data_op1_1: dts_ComList.getCellData(v_Currow, "data_op1_1"), // 금액1
            data_op1_2: dts_ComList.getCellData(v_Currow, "data_op1_2"), // 구성비1
            data_op2_1: dts_ComList.getCellData(v_Currow, "data_op2_1"), // 금액2
            data_op2_2: dts_ComList.getCellData(v_Currow, "data_op2_2"), // 구성비2
            data_op3_1: dts_ComList.getCellData(v_Currow, "data_op3_1"), // 금액3
            data_op3_2: dts_ComList.getCellData(v_Currow, "data_op3_2"), // 구성비3
            data_op4_1: dts_ComList.getCellData(v_Currow, "data_op4_1"), // 금액4
            data_op4_2: dts_ComList.getCellData(v_Currow, "data_op4_2") // 구성비4
        };
        // fn_SetPar(arrPar);

    }
    // frame.CloseFrame();

};

/**
 * @method
 * @name initialize
 * @description 상단 HEADER 부분 초기화
 * @returns {void}
 * @hidden N
 */
scwin.initialize = function() {
    $c.cm.setColumnProp(grd_ComList, "1date", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "2date", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "3date", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "4date", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "inspection1", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "inspection2", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "inspection3", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "inspection4", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op1_2", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op2_2", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op3_2", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op4_2", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op1_1", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op2_1", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op3_1", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op4_1", "Name", "");
};

/**
 * @method
 * @name getOpiText
 * @description 감사의견 세팅
 * @param {*} opiCode opiCode
 * @returns {void}
 * @hidden N
 */
scwin.getOpiText = function(opiCode) {
    let opiText = "";
    if (opiCode === "10") opiText = "적정";
    if (opiCode === "20") opiText = "한정";
    if (opiCode === "21") opiText = "한정-감사범위제한";
    if (opiCode === "22") opiText = "한정-기업회계기준위배";
    if (opiCode === "30") opiText = "부적정";
    if (opiCode === "31") opiText = "부적정 -계속기업존속의문시";
    if (opiCode === "40") opiText = "의견거절";
    if (opiCode === "41") opiText = "의견거절-독립성결";
    if (opiCode === "42") opiText = "의견거절-감사범위제한";
    if (opiCode === "43") opiText = "의견거절-계속기업존속의문시";
    if (opiCode === "50") opiText = "감사미필";
    if (opiCode === "70") opiText = "검토(표준)";
    if (opiCode === "71") opiText = "검토(한정)";
    if (opiCode === "72") opiText = "검토(부적정)";
    if (opiCode === "73") opiText = "검토(의견거절)";
    if (opiCode === "80") opiText = "미검토";
    return opiText;
};

/**
 * @method
 * @name accntCdOpen
 * @description 계정코드 변경
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.accntCdOpen = async function() {
    const options = {
        id: "ULDFIS00600_P10",
        title: "재무계정검색",
        type: "browserPopup",
        width: 683 + 20,
        height: 485 + 40,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("./ULDFIS00600_P10.gfm", options);
};
